{"title":"RigSignal — Live Differential Flamegraph (select 2 sessions)","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "RigSignal live two-session differential flamegraph. Select exactly two flame session labels with the dashboard control.",
  "autosize": { "type": "fit", "contains": "padding" },
  "padding": 5,
  "config": {
    "axis": { "domainColor": "#444", "tickColor": "#444" },
    "view": { "stroke": null }
  },
  "signals": [
    {
      "name": "swapAB",
      "value": false,
      "bind": { "input": "checkbox", "name": "Swap A / B " }
    },
    { "name": "rowHeight", "value": 18 },
    { "name": "labelMinWidth", "value": 0.035 },
    {
      "name": "labelA",
      "update": "length(data('labels')) === 2 ? (swapAB ? data('labels')[1].label : data('labels')[0].label) : ''"
    },
    {
      "name": "labelB",
      "update": "length(data('labels')) === 2 ? (swapAB ? data('labels')[0].label : data('labels')[1].label) : ''"
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "metrics-rigsignal.profiles*",
        "body": {
          "size": 10000,
          "_source": [
            "@timestamp",
            "profile.kind",
            "session.label",
            "node.depth",
            "node.x0",
            "node.x1",
            "node.width",
            "node.function",
            "node.module",
            "node.samples",
            "node.total_samples",
            "node.path_id",
            "node.parent_id"
          ],
          "sort": [
            { "node.depth": "asc" },
            { "node.x0": "asc" }
          ]
        }
      },
      "format": { "property": "hits.hits" }
    },
    {
      "name": "flame",
      "source": "raw",
      "transform": [
        { "type": "formula", "as": "d", "expr": "datum._source" },
        { "type": "filter", "expr": "datum.d && datum.d['profile.kind'] === 'flame'" },
        { "type": "formula", "as": "label", "expr": "datum.d['session.label']" },
        { "type": "formula", "as": "pathId", "expr": "datum.d['node.path_id']" },
        { "type": "formula", "as": "parentId", "expr": "datum.d['node.parent_id']" },
        { "type": "formula", "as": "treeParentId", "expr": "datum.parentId === '' ? '__flamediff_root__' : datum.parentId" },
        { "type": "formula", "as": "depth", "expr": "datum.d['node.depth']" },
        { "type": "formula", "as": "samples", "expr": "datum.d['node.samples']" },
        { "type": "formula", "as": "total", "expr": "datum.d['node.total_samples']" },
        { "type": "formula", "as": "function", "expr": "datum.d['node.function']" },
        { "type": "formula", "as": "module", "expr": "datum.d['node.module']" },
        { "type": "formula", "as": "rawFrame", "expr": "datum.module ? datum.function + ' [' + datum.module + ']' : datum.function" }
      ]
    },
    {
      "name": "labels",
      "source": "flame",
      "transform": [
        { "type": "aggregate", "groupby": ["label"], "fields": ["total"], "ops": ["max"], "as": ["total"] },
        { "type": "collect", "sort": { "field": "label", "order": "ascending" } }
      ]
    },
    {
      "name": "unionRows",
      "source": "flame",
      "transform": [
        { "type": "filter", "expr": "length(data('labels')) === 2" },
        { "type": "formula", "as": "samplesA", "expr": "datum.label === labelA ? datum.samples : 0" },
        { "type": "formula", "as": "samplesB", "expr": "datum.label === labelB ? datum.samples : 0" },
        {
          "type": "aggregate",
          "groupby": ["pathId", "treeParentId", "function", "module", "rawFrame", "depth"],
          "fields": ["samplesA", "samplesB"],
          "ops": ["sum", "sum"],
          "as": ["samplesA", "samplesB"]
        },
        { "type": "formula", "as": "unionSamples", "expr": "datum.samplesA + datum.samplesB" }
      ]
    },
    {
      "name": "childTotals",
      "source": "unionRows",
      "transform": [
        { "type": "aggregate", "groupby": ["treeParentId"], "fields": ["unionSamples"], "ops": ["sum"], "as": ["childSamples"] }
      ]
    },
    {
      "name": "unionTreeRows",
      "source": "unionRows",
      "transform": [
        { "type": "lookup", "from": "childTotals", "key": "treeParentId", "fields": ["pathId"], "values": ["childSamples"], "as": ["childSamples"] },
        { "type": "formula", "as": "exclusiveSamples", "expr": "max(0, datum.unionSamples - (datum.childSamples || 0))" }
      ]
    },
    {
      "name": "flamediffRoot",
      "values": [{ "pathId": "__flamediff_root__", "treeParentId": "", "exclusiveSamples": 0, "unionSamples": 0, "depth": -1 }]
    },
    {
      "name": "partitioned",
      "source": ["flamediffRoot", "unionTreeRows"],
      "transform": [
        { "type": "stratify", "key": "pathId", "parentKey": "treeParentId" },
        {
          "type": "partition",
          "field": "exclusiveSamples",
          "sort": { "field": ["unionSamples", "rawFrame"], "order": ["descending", "ascending"] },
          "size": [1, 1],
          "as": ["x0", "y0", "x1", "y1", "treeDepth", "children"]
        },
        { "type": "filter", "expr": "datum.treeDepth > 0" }
      ]
    },
    {
      "name": "nodes",
      "source": "partitioned",
      "transform": [
        { "type": "formula", "as": "x0", "expr": "datum.x0" },
        { "type": "formula", "as": "x1", "expr": "datum.x1" },
        { "type": "formula", "as": "depth", "expr": "datum.depth" },
        { "type": "formula", "as": "function", "expr": "datum.function" },
        { "type": "formula", "as": "module", "expr": "datum.module" },
        { "type": "formula", "as": "samplesA", "expr": "datum.samplesA" },
        { "type": "formula", "as": "samplesB", "expr": "datum.samplesB" },
        { "type": "formula", "as": "delta", "expr": "datum.samplesB - datum.samplesA" },
        { "type": "formula", "as": "totalA", "expr": "length(data('labels')) === 2 ? (swapAB ? data('labels')[1].total : data('labels')[0].total) : 1" },
        { "type": "formula", "as": "totalB", "expr": "length(data('labels')) === 2 ? (swapAB ? data('labels')[0].total : data('labels')[1].total) : 1" },
        { "type": "formula", "as": "deltaNorm", "expr": "datum.samplesB / datum.totalB - datum.samplesA / datum.totalA" },
        {
          "type": "formula",
          "as": "tooltip",
          "expr": "{'function': datum.function, 'module': datum.module, 'A label': labelA, 'B label': labelB, 'A samples': datum.samplesA, 'B samples': datum.samplesB, 'delta': datum.delta, 'delta_norm': datum.deltaNorm}"
        }
      ]
    }
  ],
  "scales": [
    { "name": "x", "type": "linear", "domain": [0, 1], "range": "width", "zero": false },
    { "name": "diffColor", "type": "linear", "domain": [-0.05, 0, 0.05], "range": ["#2f6fdd", "#f6f6f6", "#c9342f"], "clamp": true, "zero": false }
  ],
  "axes": [
    { "orient": "bottom", "scale": "x", "format": "%", "title": "Union profile width (A + B samples)" }
  ],
  "marks": [
    {
      "type": "rect",
      "from": { "data": "nodes" },
      "encode": {
        "enter": {
          "stroke": { "value": "#ffffff" },
          "strokeWidth": { "value": 0.5 },
          "tooltip": { "field": "tooltip" }
        },
        "update": {
          "x": { "scale": "x", "field": "x0" },
          "x2": { "scale": "x", "field": "x1" },
          "y": { "signal": "datum.depth * rowHeight" },
          "height": { "signal": "rowHeight - 1" },
          "fill": { "signal": "scale('diffColor', datum.deltaNorm)" },
          "cursor": { "value": "default" }
        }
      }
    },
    {
      "type": "text",
      "from": { "data": "nodes" },
      "encode": {
        "update": {
          "x": { "scale": "x", "field": "x0", "offset": 3 },
          "y": { "signal": "datum.depth * rowHeight + 12" },
          "text": { "signal": "datum.x1 - datum.x0 >= labelMinWidth ? datum.function : ''" },
          "fontSize": { "value": 11 },
          "fill": { "value": "#1f1f1f" },
          "limit": { "signal": "max(0, scale('x', datum.x1) - scale('x', datum.x0) - 6)" }
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": { "signal": "width / 2" },
          "y": { "signal": "height / 2" },
          "text": { "signal": "'Select exactly 2 session labels (profile kind: flame) — currently ' + length(data('labels')) + ' selected.'" },
          "align": { "value": "center" },
          "baseline": { "value": "middle" },
          "fontSize": { "value": 16 },
          "fontWeight": { "value": "bold" },
          "fill": { "value": "#666666" },
          "opacity": { "signal": "length(data('labels')) === 2 ? 0 : 1" }
        }
      }
    }
  ],
  "legends": [
    { "fill": "diffColor", "title": "B normalized sample share minus A", "orient": "right" }
  ]
}
"}}
